    invoice,
    amount,
    reason,
    *,
    approved_by=None,
    idempotency_key: str | None = None,
) -> dict:
    """Credit part of an issued invoice as a goodwill gesture."""
    if idempotency_key is not None:
        for event in audit.events("goodwill_credit"):
